function solution(nums, target) {
  let left = 0;
  let right = nums.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const num = nums[mid];

    if (num === target) return mid;
    num < target ? (left = mid + 1) : (right = mid - 1);
  }

  return left;
}

function solution(array) {

  const n = array.length;

    for (let i = 0; i < n; i++) {
        while (array[i] > 0 && array[i] <= n && array[array[i] - 1] !== array[i]) {
            const correctIndex = array[i] - 1;
            const temp = array[i];
            array[i] = array[correctIndex];
            array[correctIndex] = temp;
        }
    }

    for (let i = 0; i < n; i++) {
        if (array[i] !== i + 1) {
            return i + 1;
        }
    }
    return n + 1;
}

function solution(strs) {
    if (!strs || strs.length === 0)
        return "";
    for (let i = 0; strs[0].length; i++) {
        const char = strs[0][i];
        for (let j = 1; j < strs.length; j++) {
            const compChar = strs[j][i];
            if (char !== compChar) {
                return strs[0].substring(0, i);
            }
        }
    }
    return strs[0];
}

function solution(nums, target) {
  const numMap = new Map();

  for (let i = 0; i < nums.length; i++) {
    const curNum = nums[i];
    const findNum = target - curNum;

    if (numMap.has(findNum)) {
      return [numMap.get(findNum), i];
    }

    numMap.set(curNum, i);

  }

  return [];
}

function solution(str) {
    let t = 0, n = 0, b = 1;
    for (let char of str) {
        if (char.trim() === "") continue;
        if (char === "*" || char === "+") {
            b *= n;
            if (char === "+") {
                t += b;
                b = 1;
            }
            n = 0;
        } else {
            n = n * 10 + (char - '0');
        }
    }
    b *= n;
    t += b;
    return t;
}
